// Radiant time series (RTS) of one room, generated by a heat balance on the room's own surfaces.
// A 1 W radiant pulse is released for one hour (spread over all surfaces by area for non-solar
// gains, onto the floor for transmitted beam solar), the room air is held at constant temperature
// and the convective heat reaching the air is recorded hour by hour, steady-periodic over 24 h.
// This is the procedure used to generate the RTS of ASHRAE Fundamentals Ch. 18 (Spitler, Fisher &
// Pedersen 1997); outdoor and ground boundaries are held at 0, partitions see an identical room on
// the far side (adiabatic mid-plane). The series is normalised to sum to 1.
import { buildChain, H_C_IN, H_R_IN, H_OUT } from './conduction.js';

const cache = new Map();

// surfaces: [{ area, layers (outside→inside), boundary: 'outside' | 'partition' | 'ground', kind: 'floor'|'wall'|'ceiling'|'window', U (windows) }]
const sig2 = (x) => (x > 0 ? Number(x.toPrecision(2)) : 0);
export function radiantTimeSeries(surfacesIn, { dt = 30 } = {}) {
  // areas rounded to 2 significant figures: the series hardly changes, and typing stays fast (cached)
  const surfaces = surfacesIn.map((s) => ({ ...s, area: sig2(s.area), U: s.U != null ? Math.round(s.U * 10) / 10 : undefined }));
  const key = JSON.stringify(surfaces.map((s) => [s.area, s.layers, s.boundary, s.kind, s.U]));
  if (cache.has(key)) return cache.get(key);
  const S = surfaces.filter((s) => s.area > 0).map((s) => {
    if (s.kind === 'window') return { ...s, massless: true, g: 1 / Math.max(0.01, 1 / (s.U || 5.8) - 1 / (H_C_IN + H_R_IN)) };
    let layers = s.layers;
    if (s.boundary === 'partition') layers = layers.map((l) => (l.R != null ? { R: l.R / 2 } : { ...l, L: l.L / 2 }));
    if (s.boundary === 'ground') layers = [{ L: 0.3, k: 1.0, rho: 1500, c: 1.0 }, ...layers]; // soil, adiabatic below
    const { C, G } = buildChain(layers, { maxNodes: 30 });
    const n = C.length;
    return { ...s, C, G, T: new Float64Array(n), a: new Float64Array(n), b: new Float64Array(n), c: new Float64Array(n), d: new Float64Array(n),
      gOut: s.boundary === 'outside' ? H_OUT : 0, Tb: new Float64Array(n) };
  });
  const Atot = S.reduce((x, s) => x + s.area, 0);
  const floorA = S.filter((s) => s.kind === 'floor').reduce((x, s) => x + s.area, 0) || Atot;
  const run = (solar) => {
    for (const s of S) { if (s.T) s.T.fill(0); s.Ts = 0; }
    const steps = Math.round(86400 / dt), per = Math.round(3600 / dt);
    let prev = null, out = null;
    for (let day = 0; day < 40; day++) {
      out = new Array(24).fill(0);
      for (let st = 0; st < steps; st++) {
        const pulse = st < per ? 1 : 0;                                     // 1 W during hour 0
        {
          const mrt = S.reduce((x, s) => x + s.area * s.Ts, 0) / Atot; // previous step (semi-implicit)
          for (const s of S) {
            const share = solar ? (s.kind === 'floor' ? s.area / floorA : 0) : s.area / Atot;
            const q = (pulse * share) / s.area;                              // W/m² absorbed
            if (s.massless) {
              // surface node: q + hr·(mrt − Ts) + hc·(0 − Ts) + g·(0 − Ts) = 0
              s.Tn = (q + H_R_IN * mrt) / (H_R_IN + H_C_IN + s.g);
            } else {
              // inside node gets radiation exchange (linearised to MRT) and convection to air at 0
              stepWithInside(s.T, s, dt, q + H_R_IN * mrt, H_R_IN + H_C_IN);
              s.Tn = s.T[0];
            }
          }
          for (const s of S) s.Ts = s.Tn;
        }
        const conv = S.reduce((x, s) => x + H_C_IN * s.area * s.Ts, 0);
        out[Math.floor(st / per)] += conv / per;
      }
      if (prev && out.every((v, i) => Math.abs(v - prev[i]) < 1e-7)) break;
      prev = out;
    }
    const sum = out.reduce((x, y) => x + y, 0);
    return out.map((v) => v / sum);
  };
  const res = { nonsolar: run(false), solar: run(true) };
  cache.set(key, res);
  return res;
}

// one implicit step for a wall with inside node gaining src (W/m²) and losing gIn·T0 (to air + linearised radiation)
function stepWithInside(T, s, dt, src, gIn) {
  const { C, G, a, b, c, d, gOut } = s, n = T.length;
  for (let i = 0; i < n; i++) {
    const gL = i === 0 ? gIn : G[i - 1], gR = i === n - 1 ? gOut : G[i];
    a[i] = i === 0 ? 0 : -G[i - 1];
    c[i] = i === n - 1 ? 0 : -G[i];
    b[i] = C[i] / dt + gL + gR;
    d[i] = (C[i] / dt) * T[i];
  }
  d[0] += src;
  for (let i = 1; i < n; i++) { const m = a[i] / b[i - 1]; b[i] -= m * c[i - 1]; d[i] -= m * d[i - 1]; }
  T[n - 1] = d[n - 1] / b[n - 1];
  for (let i = n - 2; i >= 0; i--) T[i] = (d[i] - c[i] * T[i + 1]) / b[i];
}
